import { v } from "convex/values";
import { internalMutation, query } from "./_generated/server";
import { requireAccount } from "./auth";
import { cycleStart } from "./billing";

export const recordUsage = internalMutation({
  args: { accountId: v.id("accounts"), kind: v.string(), amount: v.number() },
  returns: v.null(),
  handler: async (ctx, args) => {
    await ctx.db.insert("usageEvents", {
      accountId: args.accountId,
      kind: args.kind,
      amount: args.amount,
      at: Date.now(),
    });
    return null;
  },
});

/** This billing cycle's transcription minutes, read from the daily aggregates rather than the raw events. */
export const currentCycleUsage = query({
  args: {},
  returns: v.object({ used: v.number(), limit: v.number(), resetsAt: v.number() }),
  handler: async (ctx) => {
    const account = await requireAccount(ctx);
    const days = await ctx.db
      .query("usageDaily")
      .withIndex("by_account_and_day", (q) =>
        q.eq("accountId", account._id).gte("day", cycleStart(account.billing)),
      )
      .collect();
    const used = days.reduce((sum, day) => sum + day.transcriptionMinutes, 0);
    return { used, limit: account.billing.minutesIncluded, resetsAt: account.billing.cycleEndsAt };
  },
});

