import { useQuery } from "convex/react";
import { api } from "../../convex/_generated/api";
import { useI18n } from "../i18n";

const WARN_AT = 0.8;

export function UsageMeter() {
  const usage = useQuery(api.usage.currentCycleUsage);
  const t = useI18n();
  if (!usage) return <div className="usage-meter usage-meter--loading" />;

  const ratio = usage.limit > 0 ? Math.min(usage.used / usage.limit, 1) : 0;
  const tone = ratio >= 1 ? "over" : ratio >= WARN_AT ? "warn" : "ok";

  return (
    <section className={`usage-meter usage-meter--${tone}`} aria-label={t("usage.title")}>
      <header>
        <h3>{t("usage.title")}</h3>
        <span>{t("usage.resets", { date: new Date(usage.resetsAt) })}</span>
      </header>
      <div
        className="usage-meter__bar"
        role="meter"
        aria-valuemin={0}
        aria-valuemax={usage.limit}
        aria-valuenow={usage.used}
      >
        <div className="usage-meter__fill" style={{ width: `${ratio * 100}%` }} />
      </div>
      <p>
        {t("usage.minutes", { used: Math.round(usage.used), limit: usage.limit })}
        {tone === "over" && <strong> {t("usage.over")}</strong>}
      </p>
    </section>
  );
}

